import turtle

mau = ["red", "green", "blue"]

def ve_vuong(canh):
    for i in range(4):
        turtle.forward(canh)
        turtle.left(90)

for m in mau:
    turtle.pencolor(m)
    ve_vuong(50)
    turtle.left(120)
